<script setup lang="ts">
const token = import.meta.client ? localStorage.getItem('coworkspace_token') : null;
if (!token) await navigateTo('/login');
const reservations = ref<unknown[]>([]);
const workspaces = ref<Array<{ id: string; name: string; address: string; rooms: Array<{ id: string; name: string; capacity: number; hourlyRate: string }> }>>([]);
const selectedRoom = ref(''); const startsAt = ref(''); const endsAt = ref(''); const message = ref('');
const config = useRuntimeConfig();
onMounted(async () => { if (token) { const headers = { Authorization: `Bearer ${token}` }; reservations.value = await $fetch<unknown[]>(`${config.public.apiBase}/reservations/mine`, { headers }).catch(() => []); } workspaces.value = await $fetch<typeof workspaces.value>(`${config.public.apiBase}/workspaces`).catch(() => []); });
async function reserve() { if (!token) return; message.value = ''; try { await $fetch(`${config.public.apiBase}/reservations`, { method:'POST', headers:{ Authorization:`Bearer ${token}` }, body:{ roomId:selectedRoom.value, startsAt:startsAt.value, endsAt:endsAt.value } }); message.value='Reserva criada com sucesso.'; } catch { message.value='Não foi possível criar a reserva.'; } }
function logout() { localStorage.removeItem('coworkspace_token'); navigateTo('/login'); }
</script>
<template><main class="dashboard"><header><strong>CoworkSpace</strong><button @click="logout">Sair</button></header><section><p class="eyebrow">PAINEL</p><h1>Reserve seu próximo espaço</h1><div class="grid"><article v-for="workspace in workspaces" :key="workspace.id" class="workspace"><h2>{{ workspace.name }}</h2><p>{{ workspace.address }}</p><select v-model="selectedRoom"><option value="">Escolha uma sala</option><option v-for="room in workspace.rooms" :key="room.id" :value="room.id">{{ room.name }} · {{ room.capacity }} pessoas</option></select></article></div><div class="booking"><label>Início<input v-model="startsAt" type="datetime-local"></label><label>Fim<input v-model="endsAt" type="datetime-local"></label><button @click="reserve">Solicitar reserva</button><p v-if="message">{{ message }}</p></div><h2>Suas reservas</h2><div v-if="reservations.length" class="list"><article v-for="reservation in reservations" :key="JSON.stringify(reservation)">{{ reservation }}</article></div><div v-else class="empty">Você ainda não possui reservas.</div></section></main></template>
<style scoped>.dashboard{min-height:100vh;background:#10131a;color:#f5f7fb}header{display:flex;justify-content:space-between;padding:1.5rem 6%;border-bottom:1px solid #2f3a50}header button{background:transparent;color:#aab4c7;border:1px solid #52617a;border-radius:.4rem;padding:.4rem .8rem}section{max-width:1000px;margin:5rem auto;padding:0 2rem}.eyebrow{color:#76a9ff;letter-spacing:.2em;font-weight:700}h1{font-size:clamp(2rem,5vw,4rem)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:1rem}.workspace,.booking{padding:1.2rem;background:#171c26;border:1px solid #2f3a50;border-radius:.8rem}.workspace p,.empty{color:#aab4c7}.workspace select,.booking input{width:100%;margin-top:.5rem;padding:.7rem;background:#10131a;color:#fff;border:1px solid #52617a;border-radius:.4rem}.booking{display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin:1.5rem 0}.booking label{display:grid}.booking button{grid-column:1/-1;padding:.8rem;background:#76a9ff;border:0;border-radius:.4rem;font-weight:700}.list article{padding:1rem;background:#171c26;border-radius:.5rem;margin:.5rem 0}.empty{padding:2rem;border:1px dashed #52617a;border-radius:1rem}</style>
